from review import card,save,DATE
i='TCS-3662';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 1.4, function classes, local oracles and high-probability complexity; Section 4, low-dimensional conjecture Ω(d·ln(1/ε)/ln(K/γ)).'
refs += [dict(id='journal',title='Lower Bounds for Parallel and Randomized Convex Optimization',authors='Jelena Diakonikolas; Cristóbal Guzmán',year=2020,url='https://www.jmlr.org/papers/v21/19-771.html',pdf_url='https://www.jmlr.org/papers/volume21/19-771/19-771.pdf',locator='JMLR 21(5), January 2020; Sections 1.3–1.4 and 5. The revised conclusion discusses the ℓ∞ conjecture and low-dimensional Euclidean parallel improvements; it does not repeat the conference formula as a fully quantified theorem.'),dict(id='highorder',title='Non-Euclidean High-Order Smooth Convex Optimization',authors='Juan Pablo Contreras; Cristóbal Guzmán; David Martínez-Rubio',year=2025,url='https://proceedings.mlr.press/v291/contreras25a.html',pdf_url='https://arxiv.org/pdf/2411.08987',locator='COLT 2025 extended abstract and full arXiv paper; Section 5 and parallel extension in Appendix D.2: nearly optimal high-dimensional smooth ℓp bounds, including the earlier p∈[1,2) gap.')]
issue='The recovered formula omits a precise joint low-dimensional regime for d,ε,K,γ, which must accompany a uniform Ω bound. The allowed norm geometry and the normalization of the function class are not fixed by the final conjecture sentence. The confidence range also matters: γ is success probability, and the displayed denominator cannot be used without qualification all the way to K=1,γ→1. The 2020 journal conclusion changes the surrounding discussion and does not supply these missing quantifiers. No arbitrary Euclidean specialization or parameter range is certified here.'
notes=['Restored d as the numerator, logarithmic accuracy factor and round rather than total-query cost.','Recovered γ as SUCCESS confidence in the source’s distributional high-probability definition, not failure probability.','Defined adaptive batches, local information and nonsmooth/Hölder/smooth distinctions.','Read the revised 2020 discussion and the 2025 high-dimensional improvement; preserved missing joint regime and geometry.']
save(i,dict(title='Low-dimensional parallel convex-optimization lower bounds',formal='In the low-dimensional regime, is the high-probability K-parallel local-oracle complexity of convex optimization at least Ω(d·ln(1/ε)/ln(K/γ)), for the nonsmooth, weakly smooth and smooth settings intended by the source? Here d is dimension, K is the number of simultaneous queries per round, ε is normalized additive optimization accuracy, and γ is the source’s success-confidence parameter. The denominator and d were damaged in the imported excerpt. The conjecture’s joint parameter regime and geometric scope still need specification before it is a fully quantified lower-bound statement.',definitions='The source considers a finite-dimensional normed space E=Rᵈ, a known closed convex feasible set X, and an unknown convex objective f:E→R from a class F. The goal is a point x∈X with f(x)−inf_{y∈X}f(y)≤ε. Its geometric settings include unit balls B_p^d={x:‖x‖ₚ≤1}, where ‖x‖ₚ=(Σᵢ|xᵢ|ᵖ)^{1/p} for finite p≥1 and ‖x‖∞=maxᵢ|xᵢ|. A local oracle O satisfies O_f(x)=O_g(x) whenever f and g agree on a neighborhood of x. Gradient or suitable local subgradient information is a special case; exact internal arithmetic is not the resource counted. In a K-parallel algorithm, a whole batch of at most K query points is chosen before any answer in that batch is seen. Later batches may depend on all previous answers. Cost is rounds of such batches, not the total K times that number of queries. For an objective class F, fixed oracle O and deterministic K-parallel algorithm A, let T(A,f,ε) be the number of rounds until A finds an ε-accurate feasible point. The source defines C_HP^γ=sup_D inf_A inf{τ: Pr_{f drawn from D}[T(A,f,ε)≤τ]≥γ}, where D ranges over probability distributions supported on F and 0<γ<1. Thus a hard distribution is chosen before the deterministic algorithm, which may know it; the distributional lower bound also constrains randomized algorithms. In this convention γ is the required success probability. Nonsmooth classes include Lipschitz convex functions, |f(x)−f(y)|≤L‖x−y‖. Weakly smooth classes have Hölder-continuous gradients, ‖∇f(x)−∇f(y)‖_*≤μ‖x−y‖^κ for 0<κ<1; κ=1 gives Lipschitz-continuous gradients. The dual norm is ‖v‖_*=sup_{‖x‖≤1}|⟨v,x⟩|. The source also uses a nonsmooth normalization through bounded variation of subgradients. Bounds in ln(1/ε) presuppose fixing these scales and the radius of X. Low-dimensional means a regime outside the dimension requirements of the source’s high-dimensional lower bounds, but that phrase alone does not prescribe a numerical relation among the parameters.',question_type='yes_no',answer_criterion='For precisely specified objective classes, geometries and a joint range of d,K,ε,γ, prove the displayed lower bound with constants uniform over that range, or refute it by a valid oracle algorithm violating the bound there. A result that assumes dimension polynomially large in inverse accuracy, treats only deterministic worst-case complexity, or uses total queries instead of rounds does not automatically establish this high-probability low-dimensional claim. The omitted parameter and class conventions must be resolved before this is a complete benchmark proposition.',context_blocks=[dict(title='The confidence convention changes the formula',text='The source’s quantile definition requires success probability at least γ. Substituting a failure probability would reverse the meaning of the parameter in ln(K/γ). The imported excerpt also detached d from its numerator.',citation='primary'),dict(title='The historical nonsmooth box bound is weaker',text='The conference conclusion compares Nemirovski’s deterministic ℓ∞ lower bound Ω((d/ln(dK))^{1/3}ln(1/ε)) with a desired linear dependence on d up to a logarithm. Its randomized argument recovers a related scale only for constant accuracy.',citation='primary'),dict(title='The journal discussion is more qualified',text='The 2020 version discusses known low-dimensional Euclidean parallel speedups and asks about other geometries. Its conclusion does not reproduce the conference’s smooth-and-nonsmooth confidence formula with full quantifiers.',citation='journal'),dict(title='The recent resolution concerns high dimensions',text='The 2025 paper improves smooth parallel lower bounds, including the previously weaker ℓ₁ exponent, under sufficiently large dimension. Its abstract’s statement that it resolves an open parallel-optimization question does not identify this low-dimensional conjecture as solved.',citation='highorder')],why='Would quantify the limits of parallel oracle queries when dimension is too small for existing high-dimensional hard instances, a regime where parallel speedups can actually occur.',references=refs,progress=[dict(date='2019',text='The COLT conclusion states the low-dimensional logarithmic-accuracy conjecture after high-dimensional and constant-accuracy results.',citation='primary'),dict(date='2020-01',text='The journal version updates the discussion with low-dimensional Euclidean speedups and a geometry-dependent open question.',citation='journal'),dict(date='2025',text='The checked higher-order work improves the high-dimensional smooth parallel bounds; that dimension condition remains material.',citation='highorder')],status='uncertain',status_note='Read the confidence definition and final formula in the conference paper, the revised journal discussion, and the 2025 full lower-bound section. Searches through 12 September 2026 did not establish the historical low-dimensional conjecture with a complete joint regime. Its confidence and geometry qualifications remain necessary, so it is not certified as a current fully specified theorem target.',model_self_contained=False,requires_context=True,statement_review=dict(status='needs_specification',reviewed_on=DATE,notes=notes,remaining_issue=issue),review_note=issue,importance=dict(score=c['importance']['score'],method='editorial',reason='A general limit on useful parallelism in low-dimensional convex optimization, sensitive to geometry and confidence. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['A parallel convex optimizer queries at most K points before seeing that round’s answers.','The source conjectures a round lower bound proportional to d·ln(1/ε)/ln(K/γ) in low dimensions.','Here γ is success confidence, and ε measures the additive gap from the optimum.','The journal revision and recent high-dimensional smooth results address related but distinct regimes.','The intended geometry, scale normalization and joint parameter range remain necessary to complete the conjecture.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','journal','highorder'])),notes=notes,checked_sources=[r['url'] for r in refs],state='improved_unfinished')
